def select_next_node(graph, unvisited_nodes):
    import numpy as np
    import networkx as nx

    pre = graph.graph.get('precomputed', {})
    bridge_ratio = pre.get('bridge_ratio_high_bc', 0.1)
    max_core = pre.get('max_core_k', 1)
    degree_variance = pre.get('degree_variance', 1.0)

    def normalize(arr):
        arr = np.array(arr, dtype=float)
        if arr.size == 0:
            return arr
        if arr.max() == arr.min():
            return np.ones_like(arr)
        return (arr - arr.min()) / (arr.max() - arr.min())

    # Shortcut: if only one node left
    if len(unvisited_nodes) == 1:
        return unvisited_nodes[0]

    subG = graph.subgraph(unvisited_nodes)
    nodelist = list(subG.nodes())
    idx_map = {n: i for i, n in enumerate(nodelist)}

    # Compute community structure with fast greedy modularity (using networkx greedy_modularity_communities)
    try:
        communities = list(nx.algorithms.community.greedy_modularity_communities(subG))
    except:
        # Fallback single community
        communities = [set(nodelist)]

    # Map node to community id
    node_community = {}
    for i, comm in enumerate(communities):
        for node in comm:
            node_community[node] = i

    # Calculate boundary strength: number of edges from node to other communities
    boundary_strengths = np.zeros(len(nodelist), dtype=float)
    for u in nodelist:
        u_idx = idx_map[u]
        comm_u = node_community[u]
        count = 0
        for nbr in graph.neighbors(u):
            if nbr in idx_map:
                if node_community.get(nbr, -1) != comm_u:
                    count += 1
        boundary_strengths[u_idx] = count

    # Normalize boundary strengths
    boundary_strengths_n = normalize(boundary_strengths) + 1e-12

    # Get node influence features normalized
    betw = np.array([graph.nodes[n]['betweenness'] for n in nodelist], dtype=float)
    eig = np.array([graph.nodes[n]['eigenvector'] for n in nodelist], dtype=float)
    betw_n = normalize(betw) + 1e-12
    eig_n = normalize(eig) + 1e-12

    # Combined influence score (weighted geometric mean)
    influence = (betw_n ** 0.6) * (eig_n ** 0.4)

    # Final score: boundary strength * influence * (1 + core_number normalized)
    core_num = np.array([graph.nodes[n]['core_number'] for n in nodelist], dtype=float)
    core_n = normalize(core_num) + 1e-12

    scores = boundary_strengths_n * influence * (1 + core_n)

    # If no node has boundary edges (all zero), fallback to influence only
    if np.all(boundary_strengths == 0):
        scores = influence * (1 + core_n)

    idx = np.argmax(scores)
    return nodelist[idx]

def select_next_node(graph, unvisited_nodes):
    import numpy as np

    pre = graph.graph.get('precomputed', {})
    bridge_ratio = pre.get('bridge_ratio_high_bc', 0.15)

    visited_nodes = set(graph.nodes()) - set(unvisited_nodes)

    def normalize(arr):
        arr = np.array(arr, dtype=float)
        if arr.size == 0:
            return arr
        if arr.max() == arr.min():
            return np.ones_like(arr)
        return (arr - arr.min()) / (arr.max() - arr.min())

    # Precompute neighbor sets for visited nodes once
    visited_neighbors = {v: set(graph.neighbors(v)) for v in visited_nodes} if visited_nodes else {}

    def jaccard_dissimilarity(u):
        # Compute average Jaccard dissimilarity of u's neighbors with visited nodes' neighbors
        u_neighbors = set(graph.neighbors(u))
        if not visited_neighbors:
            return 1.0  # max novelty if no visited nodes
        scores = []
        for v_nbrs in visited_neighbors.values():
            inter = len(u_neighbors & v_nbrs)
            union = len(u_neighbors | v_nbrs)
            if union == 0:
                scores.append(1.0)
            else:
                scores.append(1 - inter / union)
        return np.mean(scores)

    # Build arrays for features of unvisited nodes
    deg_arr = np.array([graph.nodes[n]['degree'] for n in unvisited_nodes], dtype=float)
    clust_arr = np.array([graph.nodes[n]['clustering'] for n in unvisited_nodes], dtype=float)
    core_arr = np.array([graph.nodes[n]['core_number'] for n in unvisited_nodes], dtype=float)
    betw_arr = np.array([graph.nodes[n]['betweenness'] for n in unvisited_nodes], dtype=float)

    # Normalize features individually
    inv_clust_n = normalize(1 / (clust_arr + 1e-9))  # inverse clustering
    betw_n = normalize(betw_arr)
    core_n = normalize(core_arr)

    # Compute novelty scores based on Jaccard dissimilarity of neighbors
    novelty_scores = np.array([jaccard_dissimilarity(n) for n in unvisited_nodes])
    novelty_scores = novelty_scores ** (1 + bridge_ratio * 5)  # emphasize novelty nonlinearly

    # Adaptive risk score: harmonic mean of inv_clust, betw, core weighted by novelty
    # Use harmonic mean to prioritize nodes strong in all features
    def harmonic_mean(x, y, z):
        return 3.0 / (1.0/(x+1e-12) + 1.0/(y+1e-12) + 1.0/(z+1e-12))

    risk_score = harmonic_mean(inv_clust_n, betw_n, core_n)
    weighted_score = risk_score * novelty_scores

    idx = np.argmax(weighted_score)
    next_node = unvisited_nodes[idx]

    return next_node
